mapper.select:
select * from (select aaa.* from (
) aaa left join SYS_DATADICT_LIST sdl on aaa.finprodType2=sdl.ITEM_CODE and sdl.DICT_CODE='REG_ASSET_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dicttradeMarket on aaa.tradeMarket=dicttradeMarket.ITEM_CODE and dicttradeMarket.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED' left join SYS_DATADICT_LIST dictdealType on aaa.dealType=dictdealType.ITEM_CODE and dictdealType.DICT_CODE='QUOTE_TYPE' left join SYS_DATADICT_LIST dictquote on aaa.quoteType=dictquote.ITEM_CODE and dictquote.DICT_CODE='QUOTE_STYLE'
order by aaa.finprodType2, aaa.ps DESC)
order by ${sort} ${direction}

mapper.sql:
select '有效' as effectiveStatusName, decode(reg.finprod_type2,'F01','01','F02','02','F03','02') as finprodType2, fpt.TYPE_9 as assetType, decode(reg.finprod_type2,'F01',reg.finprod_id,reg.term_type) as finprodId, decode(reg.finprod_type2,'F01',fp.finprod_market_id,reg.term_type) as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, decode(reg.finprod_type2,'F01',reg.face_value/10000,null) as faceValue, case when reg.finprod_type2='F01' then decode(regAdd.CAL_MODE,'01',ROUND(reg.unit_cprice,4), '02',ROUND(reg.yield*100,4),'FM990.0000', '03',ROUND(reg.exer_yield*100,4)) when reg.finprod_type2 in ('F02','F03') then ROUND(reg.rate*100,4) else null end as tradeYield, case when reg.finprod_type2='F01' then decode(regAdd.CAL_MODE,'01',TO_CHAR(ROUND(reg.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(reg.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(reg.exer_yield*100,4),'FM990.0000')||'%') when reg.finprod_type2 in ('F02','F03') then TO_CHAR(ROUND(reg.rate*100,4),'FM990.0000') ||'%' else null end as tradeYieldStr, reg.repo_term as termDays, reg.trade_amt as tradeAmt, reg.totle_trade_id as busiCode, coalesce ( sua.IBU_TRADER, t3.real_name, reg.ou_trader_id ) AS trader, reg.trade_date as tradeDate, reg.counter_id as counterId, nvl(t1.counter_name,reg.counter_id) as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, reg.remark as remark, reg.totle_trade_id as totleTradeId, '01' effectiveStatus, '01' regStatus, '04' as dealType, reg.settle_date as settleDate, reg.delivery_type as deliveryType, reg.v_settle_date as vsettleDate, reg.m_settle_date as msettleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues, null as execid, regAdd.CAL_MODE calMode, reg.unit_cprice as unitCprice, reg.yield*100 as yield, reg.exer_yield*100 as exerYield, reg.rate*100 as rate, reg.m_trade_amt as mtradeAmt,null ouPartyId from reg_fin_product_deal_total reg left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.Totle_Trade_Id left join fin_product fp on fp.finprod_id=reg.finprod_id left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = fp.FINPROD_ID inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from reg_fin_product_deal regdeal left join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id left join MST_COUNTER_PARTY t1 on t1.counter_id=reg.counter_id left join sys_user t3 on t3.user_name=reg.ou_trader_id LEFT JOIN sys_user_add sua ON sua.USER_ID = t3.USER_ID where reg.trade_date= #{sysDate,jdbcType=DATE} and reg.trade_status='01' and reg.is_cancel='N' AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where reg.totle_trade_id=match.pre_trade_id) and reg.ps in ('T01','T02','03','04')
and reg.ou_trader_id= #{userId}
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND reg.finprod_id in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND fpt.TYPE_9=#{assetType,jdbcType=VARCHAR}
AND decode(reg.settle_speed,0,'01',1,'02',2,'03')= #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND '04'= #{dealType,jdbcType=VARCHAR}
AND reg.counter_id IN
#{item}
union all select * from ( select '有效' effectiveStatusName, '03' finprodType2, fpt.TYPE_9 as assetType, bo.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.finprod_abbr as finprodAbbr, 'T01' ps, fp.TRADE_MARKET tradeMarket, null settleSpeed, deal.SEC_ACCT_ID secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, bo.SUBSCRIPTION_AMOUNT/10000 faceValue, case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then nvl(fpi.BP*10000, 0) when fp.COUPON_SPECIES in ('02', '03') then fpi.REFER_YIELD*100 when (fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '01') or fp.COUPON_SPECIES = '04' then fpi.REFER_YIELD*100 end tradeYield, case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then SDL.ITEM_VALUE || '+' || to_char(nvl(fpi.BP*10000, 0),'FM999990.90')||'BP' when fp.COUPON_SPECIES in ('02', '03') then to_char(fpi.REFER_YIELD*100,'FM99990.9990') || '%' when (fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '01') or fp.COUPON_SPECIES = '04' then to_char(fpi.REFER_YIELD*100,'FM99990.9990') || '%' end tradeYieldStr, null termDays, bo.PAYABLE_AMOUNT tradeAmt, bo.BID_ID busiCode, nvl(mcct.TRADER_Name, bo.OUR_TRADER) trader, bo.BID_DATE tradeDate, null counterId, null counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, null quoteType, bo.REMARK remark, bo.BID_ID totleTradeId, '01' effectiveStatus, '01' regStatus, '04' as dealType, bo.BID_DATE settleDate, null as deliveryType, null as vsettleDate, null as msettleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues, null as execid, null calMode, null as unitCprice, null as yield, null as exerYield, null as rate, null as mtradeAmt, bo.OU_PARTY_ID ouPartyId from BID_ORDER bo left join FIN_PRODUCT fp on fp.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = bo.FINPROD_ID LEFT JOIN SYS_DATADICT_LIST SDL on fpi.INT_RATE_ID = SDL.ITEM_CODE and DICT_CODE='SECRATE_DATA' left join (select INT_RATE_ID,row_number() over(partition by INT_RATE_ID order by INT_RATE_ID,EFF_DATE desc) as rn from MST_INT_RATE_INFO where EFF_DATE <= #{sysDate,jdbcType=DATE}) miri on miri.INT_RATE_ID = fpi.INT_RATE_ID and miri.rn = 1 inner join (select listagg(TEMP.PORTFOLIO_ID, ',') within group (order by TEMP.BID_ID) AS portfolioId, listagg(TEMP.PORTFOLIO_NAME, ',') within group (order by TEMP.BID_ID) AS portfolioName, TEMP.BID_ID, TEMP.SEC_ACCT_ID from ( select distinct bobp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, bobp.BID_ID, eed.SEC_ACCT_ID from BID_ORDER_BID_PRICE bobp left join ptl_portfolio pp on bobp.portfolio_id = pp.portfolio_id left join ETR_ENTRUST_DETAIL eed on eed.ENTRUST_ID = bobp.ENTRUST_ID and bobp.PORTFOLIO_ID = eed.PORTFOLIO_ID ) TEMP where 1 = 1
AND bobp.portfolio_id in
#{item}
group by TEMP.BID_ID, TEMP.SEC_ACCT_ID ) deal on deal.BID_ID = bo.BID_ID left join stl_sec_acct_info stlinfo on deal.SEC_ACCT_ID = stlinfo.sec_acct_id /*left join MST_CFETS_CUSTOMER_INFO mcci on mcci.PARTY_ID = bo.OU_PARTY_ID*/ left join MST_CFETS_CUSTOMER_TRADER mcct on mcct.TRADER_ID = bo.OUR_TRADER where bo.BID_DATE= #{sysDate,jdbcType=DATE} and bo.trade_status='01' and bo.is_cancel='N' and bo.BID_MODLE is null AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where bo.BID_ID=match.pre_trade_id)
and bo.OUR_TRADER = #{userId}
AND bo.finprod_id in
#{item}
AND fp.TRADE_MARKET=#{tradeMarket,jdbcType=VARCHAR}
AND deal.SEC_ACCT_ID in
#{item}
AND bo.BID_ID like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND '04'= #{dealType,jdbcType=VARCHAR}
AND fpt.TYPE_9=#{assetType,jdbcType=VARCHAR}
AND bo.OU_PARTY_ID IN
#{item}
)
AND ps=#{ps}
AND finprodType2 in
#{item}

where.if:
and  ((aaa.effectiveStatusName || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
  || '|' || dictps.ITEM_VALUE || '|' || dicttradeMarket.ITEM_VALUE || '|' || dictsp.ITEM_VALUE
  || '|' || aaa.secManageAcctIdName || '|' || aaa.busiCode || '|' || aaa.trader
  || '|' || aaa.counterId  || '|' || aaa.counterIdName || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
  || '|' || dictdealType.ITEM_VALUE  || '|' || dictquote.ITEM_VALUE  || '|' || aaa.remark
  like '%' || #{search} || '%')
  or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
  or aaa.tradeYieldStr=#{search} or  aaa.tradeYieldStr =#{search}||'%'
  or aaa.termDays||'' =#{search}
  or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
  or to_char(aaa.tradeDate,'yyyy-MM-dd')=#{search}
  or to_char(aaa.tradeDate,'yyyy-MM-dd') =#{year}||'-'||#{search}
  or to_char(aaa.tradeDate,'yyyy/MM/dd') =#{search}
  or to_char(aaa.tradeDate,'yyyy/MM/dd') =#{year}||'/'||#{search}
  )

mapper.select:
select * from (select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.finprodType2=sdl.ITEM_CODE and sdl.DICT_CODE='REG_ASSET_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dicttradeMarket on aaa.tradeMarket=dicttradeMarket.ITEM_CODE and dicttradeMarket.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED' left join SYS_DATADICT_LIST dictdealType on aaa.dealType=dictdealType.ITEM_CODE and dictdealType.DICT_CODE='QUOTE_TYPE' left join SYS_DATADICT_LIST dictquote on aaa.quoteType=dictquote.ITEM_CODE and dictquote.DICT_CODE='QUOTE_STYLE'
order by aaa.finprodType2, aaa.ps DESC)
order by ${sort} ${direction}

mapper.sql:
select '有效' as effectiveStatusName, '01' finprodType2, fpt.TYPE_9 as assetType, ib.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ib.ps as ps, '01' as tradeMarket, decode(ib.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, ib.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, ib.share_amt/100 as faceValue, decode(ibd.CALCULATE_FIELD,'01',ROUND(ibd.unit_cprice,4), '02',ROUND(ibd.yield*100,4), '03',ROUND(ibd.exer_yield*100,4), ROUND(ibd.yield*100,4)) as tradeYield, decode(ibd.CALCULATE_FIELD,'01',TO_CHAR(ROUND(ibd.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(ibd.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(ibd.exer_yield*100,4),'FM990.0000')||'%', TO_CHAR(ROUND(ibd.yield*100,4),'FM990.0000') ||'%') as tradeYieldStr, null as termDays, ibd.fprice_amt as tradeAmt, ib.cfets_quote_id as busiCode, coalesce ( sua.IBU_TRADER, t4.TRADER_NAME, ib.ou_trader_id ) AS trader, ib.quote_date as tradeDate, ibd.cp_party_id as counterId, mcci.PARTY_ABBR as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, ib.quote_type as quoteType, ib.remark as remark, ib.quote_id as totleTradeId, '01' effectiveStatus, '01' regStatus, ib.quote_type as dealType, ib.settle_date as settleDate, ib.delivery_type as deliveryType, null as vsettleDate, null as msettleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues, ibd.execid as execid, ibd.calculate_field as calMode, ibd.unit_cprice as unitCprice, ibd.yield*100 as yield, ibd.exer_yield*100 as exerYield, null as rate, null as mtradeAmt,null ouPartyId from ibu_quote_bond ib inner join ibu_quote_bond_det ibd on ib.quote_id=ibd.quote_id and ibd.trade_status='07' left join fin_product fp on ib.finprod_id=fp.finprod_id left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = fp.FINPROD_ID inner join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id where 1=1
AND pp.portfolio_id in
#{item}
group by ir.quote_id)deal on ib.quote_id=deal.quote_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON ibd.cp_party_id= mcci.party_id left join MST_CFETS_CUSTOMER_TRADER t4 on t4.TRADER_ID=ib.ou_trader_id left join MST_COUNTER_PARTY t1 on ibd.cp_party_id=t1.party_id left join sys_user_add sua on sua.ibu_trader=ib.OU_TRADER_ID left join sys_user t3 on t3.user_id=sua.user_id
where ib.quote_date= #{sysDate,jdbcType=DATE} and ib.trade_status='07' AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where ib.quote_id=match.pre_trade_id)
and t3.user_name= #{userId}
AND ib.ps=#{ps}
AND '01'=#{regAssetType}
AND '01'=#{tradeMarket,jdbcType=VARCHAR}
AND fpt.TYPE_9=#{assetType,jdbcType=VARCHAR}
AND decode(ib.settle_speed,0,'01',1,'02',2,'03') = #{settleSpeed,jdbcType=VARCHAR}
AND ib.sec_manage_acct_id in
#{item}
AND ib.cfets_quote_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND ib.quote_type= #{dealType,jdbcType=VARCHAR}
AND ib.quote_type= #{quoteType,jdbcType=VARCHAR}
AND t1.counter_id IN
#{item}
AND ib.finprod_id in
#{item}
AND ibd.execid = #{execid,jdbcType=VARCHAR}
union all select '有效' as effectiveStatusName, '02' finprodType2, null as assetType, ic.term_type as finprodId, ic.term_type as finprodMarketId, null as finprodAbbr, ic.repo_ps as ps, '01' as tradeMarket, decode(ic.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, ic.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, null as faceValue, ROUND(ic.rate*100,4) as tradeYield, TO_CHAR(ROUND(ic.rate*100,4),'FM990.0000') ||'%' as tradeYieldStr, ic.term as termDays, ic.fprice_amt as tradeAmt, ic.cfets_quote_id as busiCode, coalesce ( sua.IBU_TRADER, t4.TRADER_NAME, ic.ou_trader_id ) AS trader, ic.quote_date as tradeDate, ic.cp_party_id as counterId, mcci.PARTY_ABBR as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, ic.quote_type as quoteType, ic.remark as remark, ic.quote_id as totleTradeId, '01' effectiveStatus, '01' regStatus, ic.quote_type as dealType, ic.quote_date as settleDate, null as deliveryType, ic.v_settle_date as vsettleDate, ic.m_settle_date as msettleDate, icpledge.pledgeFinprodId as pledgeFinprodIds, icpledge.pledgeRatio as pledgeRatios, icpledge.pledgeFaceValue as pledgeFaceValues, ic.execid as execid, null as calMode, null as unitCprice, null as yield, null as exerYield, ic.rate*100 as rate, ic.M_TRADE_AMT as mtradeAmt,null ouPartyId from ibu_quote_crep ic left join ( select I.quote_id, listagg(I.pledge_finprod_id, ',') within group(order by I.pledge_finprod_id) as pledgeFinprodId, listagg(to_char(i.pledge_ratio,'FM99990.999999'), ',') within group(order by I.pledge_finprod_id) as pledgeRatio, listagg(I.pledge_face_value, ',') within group(order by I.pledge_finprod_id) as pledgeFaceValue from ibu_quote_crep_pledge I group by I.quote_id )icpledge on ic.quote_id=icpledge.quote_id inner join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id where 1=1
AND pp.portfolio_id in
#{item}
group by ir.quote_id)deal on ic.quote_id=deal.quote_id left join stl_sec_acct_info stlinfo on ic.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON ic.cp_party_id= mcci.party_id left join MST_CFETS_CUSTOMER_TRADER t4 on t4.TRADER_ID=ic.ou_trader_id left join MST_COUNTER_PARTY t1 on ic.cp_party_id=t1.party_id left join sys_user_add sua on sua.ibu_trader=ic.ou_trader_id left join sys_user t3 on t3.user_id=sua.user_id where ic.quote_date= #{sysDate,jdbcType=DATE} and ic.TRADE_STATUS='07' AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where ic.quote_id=match.pre_trade_id)
and t3.user_name= #{userId}
AND ic.repo_ps=#{ps}
AND '02'=#{regAssetType}
AND '01'=#{tradeMarket,jdbcType=VARCHAR}
AND decode(ic.settle_speed,0,'01',1,'02',2,'03') = #{settleSpeed,jdbcType=VARCHAR}
AND ic.sec_manage_acct_id in
#{item}
AND ic.cfets_quote_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND ic.quote_type= #{dealType,jdbcType=VARCHAR}
AND ic.quote_type= #{quoteType,jdbcType=VARCHAR}
AND 1=2
AND t1.counter_id IN
#{item}
AND ic.term_type in
#{item}
AND ic.execid = #{execid,jdbcType=VARCHAR}

mapper.select:
select 'F01' as finprodType2, ib.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ib.ps as ps, '01' as tradeMarket, ib.settle_speed as settleSpeed, ib.sec_manage_acct_id as secManageAcctId, ib.share_amt*100 as faceValue, ibd.yield tradeYield, null as termDays, ibd.fprice_amt as tradeAmt, ib.ou_trader_id as trader, ib.quote_date as tradeDate, ibd.cp_party_id as counterId, ib.quote_type as quoteType, ib.remark as remark, ib.quote_id as totleTradeId, ib.OU_PARTY_ID as ouPartyId, t3.user_name as ouTraderId, t1.counter_id as cpPartyId, ibd.CP_TRADER as cpTrader, i.OURDEPOSITACCOUNTNUMBER as secManageAcctId, ib.settle_date as settleDate, fp.ccy as ccy, ibd.unit_cprice unitCprice, ibd.unit_fprice as unitFprice, ibd.unit_int as unitInt, ibd.yield as yield, ibd.share_amt as shareAmt, ibd.par_value as parValue, ibd.fprice_amt fpriceAmt, ibd.cprice_amt as cpriceAmt, ibd.int_amt as intAmt, ibd.exer_yield as exerYield, ib.deal_fee_amt as trdFeeAmt, ib.sett_fee_amt as settleFeeAmt, ib.delivery_type as deliveryType, ib.sett_type as clearType from ibu_quote_bond ib inner join ibu_quote_bond_det ibd on ib.quote_id=ibd.quote_id and ibd.trade_status='07' left join fin_product fp on ib.finprod_id=fp.finprod_id left join trdquto_match_info match on ib.quote_id=match.pre_trade_id left join ( select i.* from interf_cstp_trade I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME )i on match.exe_id=i.execid left join MST_COUNTER_PARTY t1 on t1.party_id=ibd.CP_PARTY_ID left join sys_user_add sua on sua.ibu_trader=ib.OU_TRADER_ID left join sys_user t3 on t3.user_id=sua.user_id
where rownum=1 and ib.trade_status='07'
AND ib.quote_id= #{quoteId,jdbcType=VARCHAR}
AND ib.cfets_quote_id= #{cfetsQuoteId,jdbcType=VARCHAR}

select ic.repo_ps as ps, '01' as tradeMarket, ic.settle_speed as settleSpeed, ic.sec_manage_acct_id as secManageAcctId, ic.term as termDays, ic.FPRICE_AMT as tradeAmt, ic.ou_trader_id as trader, ic.quote_date as tradeDate, ic.quote_type as quoteType, ic.remark as remark, ic.QUOTE_ID as totleTradeId, ic.OU_PARTY_ID as ouPartyId, t3.user_name as ouTraderId, t1.counter_id as counterId, ic.CP_TRADER_ID as counterTrader, ic.V_SETTLE_DATE as settleDate, ic.deal_fee_amt as trdFeeAmt, ic.sett_fee_amt as settleFeeAmt, ic.V_DELIVERY_TYPE as deliveryType, ic.M_DELIVERY_TYPE as mdeliveryType, ic.sett_type as clearType, ic.TERM_TYPE as termType, ic.act_Days as actRepoTerm, ic.ccy as ccy, ic.rate rate, ic.m_trade_amt mtradeAmt, ic.basis basis, ic.m_int_amt as mintAmt, ic.V_SETTLE_DATE as vsettleDate, ic.M_SETTLE_DATE as msettleDate, ic.share_amt as shareAmt from IBU_QUOTE_CREP ic left join trdquto_match_info match on ic.QUOTE_ID=match.pre_trade_id left join ( select i.* from interf_cstp_trade I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME )i on match.exe_id=i.execid left join MST_COUNTER_PARTY t1 on t1.party_id=ic.CP_PARTY_ID left join sys_user_add sua on sua.ibu_trader=ic.OU_TRADER_ID left join sys_user t3 on t3.user_id=sua.user_id
where rownum=1 and ic.trade_status='07'
and ic.QUOTE_ID= #{quoteId,jdbcType=VARCHAR}
AND ic.cfets_quote_id= #{cfetsQuoteId,jdbcType=VARCHAR}

select * from (select aaa.* from (select distinct I.Execid as execid, I.Businesstype as businesstype, fp.finprod_id as finprodId, decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO',tr.secid) as finprodMarketId, decode(I.BUSINESSTYPE,'BOND',fp.finprod_abbr,'REPO',null) as finprodAbbr, nvl(ts.ps,tr.ps) as ps, decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed, nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) as acctNo,
stlinfo.sec_acct_name as acctNoName, I.LASTQTY/10000 as lastqty, decode(I.BUSINESSTYPE, 'BOND', I.yield2*100, 'REPO', I.PRICE*100) tradeYield, null tradeYieldStr, I.TRADELIMITDAYS termDays, decode(I.BUSINESSTYPE, 'BOND', I.SETTLCURRAMT, 'REPO', DECODE(I.MARKETINDICATOR, 9, I.TRADECASHAMT, 10, I.SETTLCURRAMT)) as tradeAmt, I.quoteid as quoteid, I.ourinstitutioncode as traderid, mccit.PARTY_ABBR as traderidName, su.real_name trader, I.Counterinstitutioncode as counterId, mccic.PARTY_ABBR as counterIdName, decode(I.Clearingmethod,'13','01','6','02') as clearType, nvl(ts.dealdate,tr.dealdate) as tradeDate, nvl(ts.dealtext,tr.dealtext) as remark, nvl(ts.dealno,tr.tradeid) as cstpTradeId, decode(I.deliveryType,'0','03','5','02','4','01') as deliveryType, to_date(I.Settldate,'yyyy-MM-dd') as vsettleDate, to_date(I.Settldate2,'yyyy-MM-dd') as msettleDate, nvl(ts.settdate,tr.dealdate) as settleDate, icpledge.pledgeFinprodId as pledgeFinprodIds, icpledge.pledgeRatio as pledgeRatios, icpledge.pledgeFaceValue as pledgeFaceValues, tr.MDEALAMT as mtradeAmt from INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID left join fin_product fp on ts.SECID=fp.finprod_market_id and fp.finprod_type='F01' LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID
left join stl_sec_acct_info stlinfo on nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER)=stlinfo.sec_acct_id left join ( select itr.tradeid as tradeid, listagg(fprepo.finprod_id, ',') within group(order by fprepo.finprod_id) as pledgeFinprodId, listagg(to_char(itr.CONVRATE,'FM99990.999999'), ',') within group(order by fprepo.finprod_id) as pledgeRatio, listagg(itr.FACETOTALAMT, ',') within group(order by fprepo.finprod_id) as pledgeFaceValue from INTERF_TRAD_REPOASST itr inner join fin_product fprepo on itr.SECID=fprepo.finprod_market_id and fprepo.finprod_type='F01' group by itr.tradeid )icpledge on tr.oritradeid=icpledge.tradeid LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON I.ourinstitutioncode= mccit.party_customer_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON I.Counterinstitutioncode= mccic.party_customer_id where ((I.BUSINESSTYPE='BOND' and 'Y'= #{bondSupportFlag,jdbcType=VARCHAR}) or (I.BUSINESSTYPE ='REPO' and 'Y'= #{repoSupportFlag,jdbcType=VARCHAR})) and nvl(ts.dealdate,tr.dealdate)= #{sysDate,jdbcType=DATE} AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where I.EXECID=match.exe_id)
AND I.BUSINESSTYPE = #{regAssetType}
AND (nvl(ts.SECID,tr.SECID) in
#{item}
or ts.SECID in
CONCAT(#{item},'.IB')
or fp.finprod_id in
#{item}
)
and nvl(ts.ps,tr.ps) = #{ps,jdbcType=VARCHAR}
and I.Execid LIKE CONCAT('%',CONCAT(#{execid},'%'))
and I.quoteid LIKE CONCAT('%',CONCAT(#{quoteid},'%'))
AND I.ourinstitutioncode IN
#{item}
AND I.Counterinstitutioncode IN
#{item}
and decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') = #{settleSpeed}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) IN
#{item}
and (su.USER_NAME= #{userId} or su.USER_NAME is null)
union all select distinct null as execid, 'BID' as businesstype, fp.finprod_id as finprodId, CONCAT(icb.INSTRUMENT_ID, '.IB') finprodMarketId, icb.INSTRUMENT_SHORT_NAME as finprodAbbr, 'T01' as ps, null settleSpeed, null as acctNo, null as acctNoName, icb.SUBSCRIPTION_AMOUNT * 10000 as lastqty, case when icb.ISSUE_PRICE is not null then icb.ISSUE_PRICE when icb.SPREAD is not null then icb.SPREAD when icb.COUPON_RATE is not null then icb.COUPON_RATE end tradeYield, case when icb.ISSUE_PRICE is not null then to_char(icb.ISSUE_PRICE,'FM99999999990.9990') || '元' when icb.SPREAD is not null then to_char(icb.SPREAD,'FM99999999990.90') || 'BP' when icb.COUPON_RATE is not null then to_char(icb.COUPON_RATE,'FM99999999990.9990') ||'%' end tradeYieldStr, null termDays, icb.ACTUAL_FEE as tradeAmt, null as quoteid, icb.SUBSCRIBE_INSTITUTION_ID as traderid, nvl(mccit.PARTY_ABBR,icb.SUBSCRIBE_INSTITUTION_ID) traderidName, nvl(mcct.TRADER_Name, icb.SUBMIT_USER) trader, null as counterId, null as counterIdName, null as clearType, to_date(substr(icb.SUBSCRIPTION_TIME,0,10),'yyyy-MM-dd') tradeDate, icb.FAILURE_REASONS as remark, icb.TRD_ID as cstpTradeId, null as deliveryType, null as vsettleDate, null as msettleDate, null as settleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues, null as mtradeAmt from INTERF_CSTP_BJFXJG icb left join fin_product fp on CONCAT(icb.INSTRUMENT_ID,'.IB') = fp.finprod_market_id LEFT JOIN SYS_USER_ADD sua ON icb.SUBMIT_USER = sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID = su.USER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON icb.SUBSCRIBE_INSTITUTION_ID = mccit.PARTY_ID left join MST_CFETS_CUSTOMER_TRADER mcct on mcct.TRADER_ID = icb.SUBMIT_USER where NOT EXISTS(SELECT 1 FROM trdquto_match_info match where icb.TRD_ID = match.CSTP_TRADE_ID) and to_date(substr(icb.SUBSCRIPTION_TIME,0,10),'yyyy-MM-dd')= #{sysDate,jdbcType=DATE}
AND 'BID' = #{regAssetType,jdbcType=VARCHAR}
AND (fp.finprod_market_id in
#{item}
or fp.finprod_market_id in
CONCAT(#{item},'.IB')
or fp.finprod_id in
#{item}
)
and 'T01' = #{ps,jdbcType=VARCHAR}
and 1 = 2
and 1 = 2
and 'Y'= #{bidSupportFlag,jdbcType=VARCHAR}
AND icb.SUBSCRIBE_INSTITUTION_ID IN
#{item}
AND 1 = 2
and 1 = 2
AND 1 = 2
and (su.USER_NAME= #{userId} or su.USER_NAME is null)
)aaa left join SYS_DATADICT_LIST sdl on aaa.businesstype=sdl.ITEM_CODE and sdl.DICT_CODE='CSTP_BUSINESS_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictct on aaa.clearType=dictct.ITEM_CODE and dictct.DICT_CODE='CLEAR_TYPE' left join SYS_DATADICT_LIST dictss on aaa.settleSpeed=dictss.ITEM_CODE and dictss.DICT_CODE='ACCOUNT_SPEED'
order by aaa.businesstype,aaa.ps,aaa.finprodMarketId)
order by ${sort} ${direction}

where.if:
and ((aaa.execid || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dictss.ITEM_VALUE
|| '|' || aaa.acctNoName || '|' || aaa.quoteid  || '|' || aaa.traderidName || '|' || aaa.trader
|| '|' || aaa.counterIdName || '|' || dictct.ITEM_VALUE || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.lastqty,'FM9999999999999990.90')=#{search} or to_char(aaa.lastqty)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or to_char(aaa.tradeDate,'yyyy-MM-dd')=#{search}
or to_char(aaa.tradeDate,'yyyy-MM-dd') =#{year}||'-'||#{search}
or to_char(aaa.tradeDate,'yyyy/MM/dd') =#{search}
or to_char(aaa.tradeDate,'yyyy/MM/dd') =#{year}||'/'||#{search}
)

mapper.select:
select * from (select aaa.* from (select distinct m.seqno as seqno, m.match_type as matchType, reg.totle_trade_id as busiCode, m.exe_id as execid, m.CSTP_TRADE_ID as cstpTradeId, decode(reg.finprod_type2, 'F01', 'BOND', 'REPO') as finprodType2, decode(reg.finprod_type2, 'F01', '债券', '质押式回购') as finprodType2Name, fpt.TYPE_9 as assetType, sdl.ITEM_VALUE as assetTypeName, fp.finprod_id as finprodId, decode(reg.finprod_type2, 'F01', fp.finprod_market_id, reg.term_type) as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.settle_speed as settleSpeed, nvl(ts.OURDEPOSITACCOUNTNUMBER, tr.OURDEPOSITACCOUNTNUMBER) as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, case when reg.finprod_type2 = 'F01' then reg.face_value / 10000 end as printAmt, case when reg.finprod_type2 = 'F01' then decode(regAdd.CAL_MODE, '01', TO_CHAR(ROUND(reg.unit_cprice, 4), 'FM990.0000'), '02', TO_CHAR(ROUND(reg.yield * 100, 4), 'FM990.0000') || '%', '03', TO_CHAR(ROUND(reg.exer_yield * 100, 4), 'FM990.0000') || '%') when reg.finprod_type2 in ('F02', 'F03') then TO_CHAR(ROUND(reg.rate * 100, 4), 'FM990.0000') || '%' else null end as tradeYield, reg.repo_term as termDays, decode(reg.finprod_type2, 'F01', reg.fprice_amt, tr.repoamt) as tradeAmt, reg.trade_date as tradeDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, regfee.trdFeeAmt as trdFeeAmt, regfee.settleFeeAmt as settleFeeAmt, reg.counter_id as counterId, t1.counter_name as counterIdName, reg.quote_type as quoteType, m.trd_conf_status as trdConfStatus, m.match_status as matchStatus, '04' as dealType, m.pre_trade_id as totleTradeId from trdquto_match_info m inner join reg_fin_product_deal_total reg on m.pre_trade_id = reg.totle_trade_id left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id = regAdd.Totle_Trade_Id left join fin_product fp on reg.finprod_id = fp.finprod_id left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = reg.FINPROD_ID left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE = 'CUSTOM_ASSET_TYPE_TWO' and sdl.ITEM_CODE = fpt.TYPE_9 inner join( select regdeal.totle_trade_id, wm_concat(regdeal.portfolio_id) as portfolioId, wm_concat(pp.portfolio_name) portfolioName from reg_fin_product_deal regdeal left join ptl_portfolio pp on regdeal.portfolio_id = pp.portfolio_id where 1 = 1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id)deal on reg.totle_trade_id=deal.totle_trade_id left join ( select fee.trade_id,sum(decode(fee.fee_type,'B06',fee.fee_amt)) as trdFeeAmt, sum(decode(fee.fee_type,'B08',fee.fee_amt)) as settleFeeAmt from reg_trade_fee_total fee group by fee.trade_id ) regfee on reg.totle_trade_id=regfee.trade_id left join (SELECT I.* FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID, MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME) ct on ct.EXECID = m.exe_id left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid =m.exe_id and tr.Tradeid=m.cstp_trade_id left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = m.exe_id and ts.Dealno=m.cstp_trade_id left join stl_sec_acct_info stlinfo on nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER)=stlinfo.sec_acct_id LEFT JOIN MST_COUNTER_PARTY t1 on t1.counter_id=reg.counter_id where reg.trade_date= #{sysDate,jdbcType=DATE} and reg.ps in ('T01','T02','03','04')
and reg.ou_trader_id= #{userId}
AND reg.ps = #{ps}
AND ct.BUSINESSTYPE = #{finprodType2}
AND aaa.fpt.TYPE_9 = #{assetType}
AND reg.finprod_id in
#{item}
AND '04' = #{dealType}
and reg.settle_speed = #{settleSpeed}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) IN
#{item}
and m.exe_id LIKE CONCAT('%',CONCAT(#{exeid},'%'))
and reg.totle_trade_id LIKE CONCAT('%',CONCAT(#{busiCode},'%'))
and m.match_type= #{matchType}
AND reg.counter_id IN
#{item}
AND m.trd_conf_status IN
#{item}
union all select m.seqno as seqno, m.match_type as matchType, nvl(ib.cfets_quote_id, ic.cfets_quote_id) as busiCode, m.exe_id as execid, m.CSTP_TRADE_ID as cstpTradeId, ct.BUSINESSTYPE as finprodType2, decode(ct.BUSINESSTYPE, 'BOND', '债券', 'REPO', '质押式回购') as finprodType2Name, fpt.TYPE_9 as assetType, sdl.ITEM_VALUE as assetTypeName, fp.finprod_id as finprodId, decode(ct.BUSINESSTYPE, 'BOND', fp.finprod_market_id, 'REPO', ic.term_type) as finprodMarketId, decode(ct.BUSINESSTYPE, 'BOND', fp.finprod_abbr, null) as finprodAbbr, nvl(ib.ps, ic.repo_ps) as ps, nvl(ib.settle_speed, ic.settle_speed) as settleSpeed, nvl(ts.OURDEPOSITACCOUNTNUMBER, tr.OURDEPOSITACCOUNTNUMBER) as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, decode(ct.BUSINESSTYPE, 'BOND', ib.share_amt / 100, null) as printAmt, decode(ct.BUSINESSTYPE, 'BOND', ib.tradeYield, TO_CHAR(ROUND(ic.rate * 100, 4), 'FM990.0000') || '%') as tradeYield, decode(ct.BUSINESSTYPE, 'REPO', ic.term, null) as termDays, decode(ct.BUSINESSTYPE, 'BOND', ib.fprice_amt, tr.repoamt) as tradeAmt, nvl(ib.quote_date, ic.quote_date) as tradeDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, deal.trdFeeAmt as trdFeeAmt, deal.settleFeeAmt as settleFeeAmt, nvl(ib.cp_party_id, ic.cp_party_id) as counterId, mccic.PARTY_ABBR as counterIdName, nvl(ib.quote_type, ic.quote_type) as quoteType, m.trd_conf_status as trdConfStatus, m.match_status as matchStatus, nvl(ib.quote_type, ic.quote_type) as dealType, m.pre_trade_id as totleTradeId from trdquto_match_info m left join ( select t1.quote_id, t1.ps, t1.settle_speed, t1.share_amt, t1.finprod_id, t1.quote_type, t2.yield, t2.fprice_amt, t1.quote_date, t2.cp_party_id, t1.OU_TRADER_ID, t1.cfets_quote_id, decode(t2.CALCULATE_FIELD, '01', TO_CHAR(ROUND(t2.unit_cprice, 4), 'FM990.0000'), '02', TO_CHAR(ROUND(t2.yield * 100, 4), 'FM990.0000') || '%', '03', TO_CHAR(ROUND(t2.exer_yield * 100, 4), 'FM990.0000') || '%', TO_CHAR(ROUND(t2.yield * 100, 4), 'FM990.0000') || '%') as tradeYield from ibu_quote_bond t1 inner join ibu_quote_bond_det t2 on t1.quote_id = t2.quote_id where t1.TRADE_STATUS = '07' and t2.TRADE_STATUS = '07' ) ib on m.pre_trade_id = ib.quote_id left join ibu_quote_crep ic on m.pre_trade_id = ic.quote_id and ic.TRADE_STATUS = '07' left join fin_product fp on ib.finprod_id = fp.finprod_id left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = ib.FINPROD_ID left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE = 'CUSTOM_ASSET_TYPE_TWO' and sdl.ITEM_CODE = fpt.TYPE_9 inner join( select ir.quote_id, wm_concat(ir.portfolio_id) as portfolioId, wm_concat(pp.portfolio_name) portfolioName, sum(ir.deal_fee_amt) as trdFeeAmt, sum(ir.sett_fee_amt) as settleFeeAmt from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id = pp.portfolio_id where 1 = 1
AND ir.portfolio_id in
#{item}
group by ir.quote_id)deal on m.pre_trade_id=deal.quote_id left join (SELECT I.* FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID, MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME) ct on ct.EXECID = m.exe_id left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid =m.exe_id and tr.Tradeid=m.cstp_trade_id left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = m.exe_id and ts.Dealno=m.cstp_trade_id left join stl_sec_acct_info stlinfo on nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER)=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON nvl(ib.cp_party_id,ic.cp_party_id)= mccic.party_id left join MST_COUNTER_PARTY t1 on nvl(ib.cp_party_id,ic.cp_party_id)=t1.party_id left join sys_user_add sua on nvl(ib.OU_TRADER_ID,ic.ou_trader_id)=sua.ibu_trader left join sys_user t3 on t3.user_id=sua.user_id where ct.BUSINESSTYPE in ('BOND','REPO') and (ic.quote_id is not null or ib.quote_id is not null) and nvl(ib.quote_date,ic.quote_date)=#{sysDate,jdbcType=DATE}
and t3.user_name= #{userId}
AND nvl(ib.ps,ic.repo_ps) = #{ps}
AND ct.BUSINESSTYPE = #{finprodType2}
AND aaa.fpt.TYPE_9 = #{assetType}
AND ib.finprod_id in
#{item}
AND nvl(ib.quote_type,ic.quote_type) = #{dealType}
and nvl(ib.settle_speed,ic.settle_speed) = #{settleSpeed}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) IN
#{item}
and m.exe_id LIKE CONCAT('%',CONCAT(#{exeid},'%'))
and nvl(ib.cfets_quote_id,ic.cfets_quote_id) LIKE CONCAT('%',CONCAT(#{busiCode},'%'))
and m.match_type= #{matchType}
AND t1.counter_id IN
#{item}
AND m.trd_conf_status IN
#{item}
union all select distinct m.seqno as seqno, m.match_type as matchType, bo.BID_ID as busiCode, m.exe_id as execid, m.CSTP_TRADE_ID as cstpTradeId, 'BID' as finprodType2, '一级申购' as finprodType2Name, fpt.TYPE_9 as assetType, sdl.ITEM_VALUE as assetTypeName, fp.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, 'T01' as ps, null as settleSpeed, deal.SEC_ACCT_ID as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, bo.SUBSCRIPTION_AMOUNT/10000 as printAmt, /*case when icb.ISSUE_PRICE is not null then TO_CHAR(icb.ISSUE_PRICE,'FM99990.9990') || '元' when icb.SPREAD is not null then TO_CHAR(icb.SPREAD,'FM99990.90') || 'BP' when icb.COUPON_RATE is not null then to_char(icb.COUPON_RATE,'FM990.9990') ||'%' end tradeYield,*/ case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then SDL_SD.ITEM_VALUE || '+' || to_char(nvl(fpi.BP*10000, 0),'FM999990.90')||'BP' when fp.COUPON_SPECIES in ('02', '03') then to_char(fpi.REFER_YIELD*100,'FM99990.9990') || '%' when (fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '01') or fp.COUPON_SPECIES = '04' then to_char(fpi.REFER_YIELD*100,'FM99990.9990') || '%' end tradeYield, null as termDays, bo.PAYABLE_AMOUNT as tradeAmt, bo.BID_DATE as tradeDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, null as trdFeeAmt, bo.SETT_FEE_AMT as settleFeeAmt, null as counterId, null as counterIdName, null as quoteType, m.trd_conf_status as trdConfStatus, m.match_status as matchStatus, '04' as dealType, m.pre_trade_id as totleTradeId from trdquto_match_info m inner join BID_ORDER bo on m.pre_trade_id = bo.BID_ID left join fin_product fp on bo.finprod_id = fp.finprod_id left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = bo.FINPROD_ID LEFT JOIN SYS_DATADICT_LIST SDL_SD on fpi.INT_RATE_ID = SDL_SD.ITEM_CODE and SDL_SD.DICT_CODE='SECRATE_DATA' left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE = 'CUSTOM_ASSET_TYPE_TWO' and sdl.ITEM_CODE = fpt.TYPE_9 inner join(select bobp.BID_ID, eed.SEC_ACCT_ID, wm_concat(bobp.portfolio_id) as portfolioId, wm_concat(pp.portfolio_name) portfolioName from BID_ORDER_BID_PRICE bobp left join ptl_portfolio pp on bobp.portfolio_id = pp.portfolio_id left join ETR_ENTRUST_DETAIL eed on eed.ENTRUST_ID = bobp.ENTRUST_ID and eed.PORTFOLIO_ID = bobp.PORTFOLIO_ID where 1 = 1 group by bobp.BID_ID,eed.SEC_ACCT_ID) deal on bo.BID_ID = deal.BID_ID left join INTERF_CSTP_BJFXJG icb on icb.TRD_ID = m.CSTP_TRADE_ID left join stl_sec_acct_info stlinfo on deal.SEC_ACCT_ID = stlinfo.sec_acct_id where bo.BID_DATE = #{sysDate,jdbcType=DATE}
and bo.OUR_TRADER= #{userId}
AND aaa.fpt.TYPE_9 = #{assetType}
AND bo.finprod_id in
#{item}
AND icb.SUBMIT_USER IN
#{item}
and bo.BID_ID LIKE CONCAT('%',CONCAT(#{busiCode},'%'))
and m.match_type= #{matchType}
AND m.trd_conf_status IN
#{item}
)aaa left join SYS_DATADICT_LIST sdl on aaa.matchType=sdl.ITEM_CODE and sdl.DICT_CODE='TRD_MATCH_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictquoteTpe on aaa.dealType=dictquoteTpe.ITEM_CODE and dictquoteTpe.DICT_CODE='QUOTE_TYPE'
order by aaa.matchType,aaa.quoteType,aaa.assetType,aaa.ps,aaa.finprodMarketId)
order by ${sort} ${direction}

if.where:
((aaa.execid || '|' || aaa.busiCode || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId
|| '|' || aaa.finprodAbbr || '|' || dictps.ITEM_VALUE
|| '|' || aaa.assetTypeName || '|T+' || aaa.settleSpeed
|| '|' || aaa.secManageAcctIdName || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
|| '|' || aaa.counterIdName || '|' || dictquoteTpe.ITEM_VALUE
like '%' || #{search} || '%')
or to_char(aaa.printAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.printAmt)=#{search}
or aaa.tradeYield=#{search} or  aaa.tradeYield =#{search}||'%'
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or to_char(aaa.trdFeeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.trdFeeAmt)=#{search}
or to_char(aaa.settleFeeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.settleFeeAmt)=#{search}
or to_char(aaa.tradeDate,'yyyy-MM-dd')=#{search}
or to_char(aaa.tradeDate,'yyyy-MM-dd') =#{year}||'-'||#{search}
or to_char(aaa.tradeDate,'yyyy/MM/dd') =#{search}
or to_char(aaa.tradeDate,'yyyy/MM/dd') =#{year}||'/'||#{search}
)

    AND aaa.finprodType2 = #{finprodType2}

mapper.select:
select * from ( select bo.BID_ID busiCode ,'04' busiType , bo.BID_DATE tradeDate , fp.FINPROD_ID finprodId , fp.FINPROD_MARKET_ID finprodMarketId , fp.FINPROD_ABBR finprodAbbr , deal.SEC_ACCT_ID secManageAcctId , stlinfo.SEC_ACCT_NAME secManageAcctIdName
, bo.SUBSCRIPTION_AMOUNT/10000 subscriptionAmount , bo.PAYABLE_AMOUNT payableAmount , bo.SETT_FEE_AMT settFeeAmt , portfolioId , portfolioName , fpi.ISSUE_PRICE issuePrice , case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then nvl(fpi.BP*10000, 0) when fp.COUPON_SPECIES in ('02', '03') then fpi.REFER_YIELD*100 when (fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '01') or fp.COUPON_SPECIES = '04' then fpi.REFER_YIELD*100 end rate , case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then SDL.ITEM_VALUE || '+' || to_Char(nvl(fpi.BP*10000, 0),'FM999990.90')||'BP' when fp.COUPON_SPECIES in ('02', '03') then to_Char(fpi.REFER_YIELD*100,'FM999990.9990')||'%' when (fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '01') or fp.COUPON_SPECIES = '04' then to_Char(fpi.REFER_YIELD*100,'FM999990.9990')||'%' end rateStr , fpi.ISSUE_DATE issueDate , fpi.PAY_DATE payDate , fp.COUPON_SPECIES couponRateType , fpi.INT_TYPE ratetype , fp.CCY ccy , bo.OU_PARTY_ID ouPartyId , mcci.PARTY_ABBR ouPartyIdAbbr , bo.OUR_TRADER ourTrader , mcct.TRADER_NAME ourTraderName , bo.REMARK remark ,'BID' as finprodType2 from BID_ORDER bo left join FIN_PRODUCT fp on fp.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = bo.FINPROD_ID LEFT JOIN SYS_DATADICT_LIST SDL on fpi.INT_RATE_ID = SDL.ITEM_CODE and DICT_CODE='SECRATE_DATA' left join (select bobp.BID_ID, eed.SEC_ACCT_ID, wm_concat(bobp.portfolio_id) as portfolioId, wm_concat(pp.portfolio_name) portfolioName from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST_DETAIL eed on eed.ENTRUST_ID = bobp.ENTRUST_ID and bobp.PORTFOLIO_ID = eed.PORTFOLIO_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = bobp.PORTFOLIO_ID group by bobp.BID_ID, eed.SEC_ACCT_ID ) deal on deal.BID_ID = bo.BID_ID left join stl_sec_acct_info stlinfo on deal.SEC_ACCT_ID = stlinfo.sec_acct_id left join MST_CFETS_CUSTOMER_INFO mcci on mcci.PARTY_ID = bo.OU_PARTY_ID left join MST_CFETS_CUSTOMER_TRADER mcct on mcct.TRADER_ID = bo.OUR_TRADER where bo.BID_ID=#{busiCode,jdbcType=VARCHAR} )
order by ${sort} ${direction}

SELECT count(*)
from Trdquto_Match_Info t
where  1=1

  and t.pre_trade_id=#{preTradeId,jdbcType=VARCHAR}


    and t.EXE_ID=#{exeId,jdbcType=VARCHAR}

SELECT reg.totle_trade_id as totleTradeId from reg_fin_product_deal_total reg where reg.trade_status='01' and reg.is_cancel='N'
AND reg.totle_trade_id =#{totleTradeId,jdbcType=VARCHAR}
union all select ib.quote_id as totleTradeId from ibu_quote_bond ib where ib.trade_status='07'
AND ib.quote_id= #{totleTradeId,jdbcType=VARCHAR}
union all select ic.quote_id as totleTradeId from ibu_quote_crep ic where ic.TRADE_STATUS='07'
AND ic.quote_id =#{totleTradeId,jdbcType=VARCHAR}
union all select bo.BID_ID as totleTradeId from BID_ORDER bo where bo.trade_status='01' and bo.is_cancel='N'
AND bo.BID_ID =#{totleTradeId,jdbcType=VARCHAR}

select inv_aim
from etr_entrust
where entrust_id=#{entrustId,jdbcType=VARCHAR}

select reg.trade_date as tradeDate,
reg.finprod_id as finprodId,
reg.trade_market as tradeMarket,
reg.ps as ps,
reg.settle_speed as settleSpeed,
reg.sec_manage_acct_id as secManageAcctId,
reg.yield as tradeYield,
reg.yield as yield,
reg.face_value as faceValue,
reg.settle_date as settleDate,
reg.delivery_type as deliveryType,
reg.finprod_type2  as finprodType2,
fp.finprod_market_id as finprodMarketId,
reg.totle_trade_id as totleTradeId,
reg.trade_Amt as tradeAmt,
reg.repo_term as termDays,
reg.rate as rate,
reg.v_settle_date as vsettleDate,
reg.m_settle_date as msettleDate
from reg_fin_product_deal_total reg
left join fin_product fp
on reg.finprod_id=fp.finprod_id
where reg.trade_market='01' and reg.TRADE_STATUS='01' and reg.IS_CANCEL='N'
AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where reg.totle_trade_id=match.PRE_TRADE_ID)

    and reg.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR}


    and reg.finprod_type2 = #{finprodType2,jdbcType=VARCHAR}


    and to_char(reg.trade_date,'yyyy-MM-dd') = #{tradeDate,jdbcType=VARCHAR}


    and fp.finprod_market_id = #{finprodMarketId,jdbcType=VARCHAR}


    and reg.ps = #{ps,jdbcType=VARCHAR}


    and  decode(reg.settle_speed,0,'01',1,'02',2,'03') = #{settleSpeed,jdbcType=VARCHAR}


    and reg.sec_manage_acct_id = #{secManageAcctId,jdbcType=VARCHAR}


    and to_char(reg.yield,'FM990.9999')=to_char(#{yield},'FM990.9999')


    and reg.face_value=#{faceValue}


    and to_char(reg.settle_date,'yyyy-MM-dd') = #{settleDate,jdbcType=VARCHAR}


    and reg.delivery_type = #{deliveryType,jdbcType=VARCHAR}


    and reg.repo_term = #{termDays}


    and to_char(reg.rate,'FM990.9999')=to_char(#{rate},'FM990.9999')


    and to_char(reg.v_settle_date,'yyyyMMdd') = #{vsettleDate,jdbcType=VARCHAR}


    and to_char(reg.m_settle_date,'yyyyMMdd') = #{msettleDate,jdbcType=VARCHAR}


    and reg.trade_Amt=#{tradeAmt,jdbcType=VARCHAR}

select bo.BID_ID totleTradeId
from BID_ORDER bo
    left join FIN_PRODUCT fp on fp.FINPROD_ID = bo.FINPROD_ID
    left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = bo.FINPROD_ID
    where bo.TRADE_STATUS = '01' and bo.IS_CANCEL = 'N'
        AND NOT EXISTS (SELECT 1 FROM trdquto_match_info match where bo.BID_ID = match.PRE_TRADE_ID)

            and bo.BID_ID=#{totleTradeId,jdbcType=VARCHAR}


            and fp.finprod_type2 = #{finprodType2,jdbcType=VARCHAR}


            and to_char(bo.BID_DATE,'yyyy-MM-dd') = #{tradeDate,jdbcType=VARCHAR}


            and fp.finprod_market_id = #{finprodMarketId,jdbcType=VARCHAR}


            and bo.OU_PARTY_ID = #{ouPartyId,jdbcType=VARCHAR}


            and bo.SUBSCRIPTION_AMOUNT = #{subscriptionAmount,jdbcType=DECIMAL}


            and fpi.REFER_YIELD = #{couponRate,jdbcType=DECIMAL}


            and fpi.BP = #{spread,jdbcType=DECIMAL}


            and fp.ISSUE_PRICE = #{issuePrice,jdbcType=DECIMAL}


            and bo.OUR_TRADER = #{ourTrader,jdbcType=VARCHAR}


            and bo.PAYABLE_AMOUNT = #{payableAmount,jdbcType=DECIMAL}

select ENTRUST_ID trdId from WFL_ETR_ENTRUST where FINPROD_ID = #{finprodId,jdbcType=VARCHAR} and FINPROD_TYPE2 = 'F32'
union all
select BID_ID trdId from WFL_BID_ORDER where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

select ee.ENTRUST_ID,nvl(efs.finishAmt,0) ENTRUST_AMT,ee.ENTRUST_STATUS,ee.REMARK from ETR_ENTRUST ee left join (select ENTRUST_ID, sum(ENT_FINISH_AMT) finishAmt from ETR_FINISH_STATUS group by ENTRUST_ID) efs on ee.ENTRUST_ID = efs.ENTRUST_ID where ee.ENTRUST_STATUS in ('03','02')
AND ee.FINPROD_ID in
#{item}

select ENTRUST_NUM
from ETR_ENTRUST_DETAIL
where ENTRUST_ID = #{entrustId}
  and PORTFOLIO_ID = #{portfolioId}
  and ROWNUM = 1
